import{_ as t,o as a,c as s,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Extracurricular activities","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/vie-scolaire/activites-extrascolaires.md","filePath":"src/en/guide/vie-scolaire/activites-extrascolaires.md"}'),i={name:"en/guide/vie-scolaire/activites-extrascolaires.md"};function n(o,e,c,l,d,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="extracurricular-activities" tabindex="-1">Extracurricular activities <a class="header-anchor" href="#extracurricular-activities" aria-label="Permalink to &quot;Extracurricular activities&quot;">​</a></h1><p>This page covers taking attendance for extracurricular activity sessions (swimming, drama, etc.). The activities and their sessions are created by the administrator — see <a href="/era-guide/en/guide/admin/activites-extrascolaires.html">Extracurricular activities (admin)</a> — this page only covers taking attendance.</p><h2 id="take-attendance-for-a-session" tabindex="-1">Take attendance for a session <a class="header-anchor" href="#take-attendance-for-a-session" aria-label="Permalink to &quot;Take attendance for a session&quot;">​</a></h2><ol><li>Open <strong>School life → Extracurricular attendance</strong>. The list shows the scheduled sessions, with the activity, site, department and the session&#39;s day/time.</li><li>Click <strong>Take attendance</strong> on the relevant session.</li><li>Change the date at the top of the page if you need to take attendance for an occurrence of the session other than the current day&#39;s.</li><li>For each student enrolled in this session&#39;s level at this site, tap <strong>Present</strong> or <strong>Absent</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>If no session is scheduled, or no student is enrolled in the relevant level at this site, the page says so.</p><div class="tip custom-block"><p class="custom-block-title">A roll call built for phones</p><p>Each student has a <strong>Present</strong> / <strong>Absent</strong> switch; everyone starts as <strong>Present</strong>, and the <strong>Everyone present</strong> button resets the whole list to that status. The counters above the list update on every tap, and the bottom bar shows &quot;Unsaved changes&quot; until you click <strong>Save</strong> — leaving the page or changing the date at that point asks for confirmation. Attendance can&#39;t be recorded for a future date.</p></div>',6)])])}const v=t(i,[["render",n]]);export{g as __pageData,v as default};
